/* Application layer: route registry, shell, memory state, access checks and feedback. */
window.App={routes:[],groups:[],current:null,
 register(config){this.groups.push(config);this.routes.push(...config.routes);},
 start(){this.renderShell();document.addEventListener('click',e=>this.handleClick(e));document.addEventListener('change',e=>this.handleChange(e));document.addEventListener('input',e=>{if(e.target.matches('[data-filter]')){const q=e.target.value.toLowerCase();document.querySelectorAll('tr[data-search]').forEach(r=>r.hidden=!r.dataset.search.toLowerCase().includes(q));}});document.addEventListener('submit',e=>this.handleSubmit(e));window.addEventListener('hashchange',()=>this.renderRoute());if(!location.hash)location.hash='#/overview/home';this.renderRoute();},
 allowed(route){const role=DB.state.identity;const p=DB.permissions[role]||[];return p.includes('*')||p.includes(route.permission||route.group);},
 renderShell(){const nav=this.groups.map(g=>{const rs=g.routes.filter(r=>this.allowed(r));if(!rs.length)return '';return `<div class="nav-label">${g.label}</div><div class="nav-list">${rs.map(r=>`<a class="nav-link" href="#/${r.path}" data-route="${r.path}"><span class="nav-icon">${r.icon||'·'}</span><span>${r.title}</span>${r.badge?`<span class="nav-count">${r.badge}</span>`:''}</a>`).join('')}</div>`}).join('');document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-symbol">F.</div><div><div class="brand-name">FRAMEWORK</div><div class="brand-sub">AI PRODUCTION OS / 07</div></div></div><div class="side-context"><small>当前工作空间</small><strong><i class="tenant-dot"></i><span id="side-tenant">${this.tenantName()}</span></strong></div><nav>${nav}</nav><div class="sidebar-foot"><b>V7 / FROM ZERO</b><br>企业内部多租户 · AI 独立制作<br>演示数据仅存在当前页面内存</div></aside><main class="main"><header class="topbar"><div class="crumb">FRAMEWORK <span class="muted">/</span> <b id="crumb-title">工作总览</b></div><div class="top-actions"><select class="top-select" id="tenant-select" aria-label="切换租户" ${this.availableTenants().length?'':'hidden'}>${this.availableTenants().map(t=>`<option value="${t.id}" ${t.id===DB.state.tenant?'selected':''}>${t.name}</option>`).join('')}</select><select class="top-select" id="identity-select" aria-label="切换演示身份">${DB.identities.map(i=>`<option value="${i.role}" ${i.role===DB.state.identity?'selected':''}>${i.label}</option>`).join('')}</select><div class="avatar" id="user-avatar">${DB.identities.find(i=>i.role===DB.state.identity).user.slice(0,1)}</div><div class="user-meta"><b id="user-name">${DB.identities.find(i=>i.role===DB.state.identity).user}</b><span id="user-role">${DB.roleNames[DB.state.identity]}</span></div></div></header><div id="view"></div></main></div>`;},
 availableTenants(){const identity=DB.identities.find(i=>i.role===DB.state.identity);return DB.tenants.filter(t=>(identity?.tenants||[]).includes(t.id)&&t.status!=='已归档');},
 tenantName(){return DB.tenants.find(t=>t.id===DB.state.tenant)?.name||(DB.state.identity==='platform'?'平台运维域':'未选择租户');},
 renderRoute(){const path=decodeURIComponent(location.hash.replace(/^#\/?/,'' )||'overview/home').split('?')[0];const route=this.routes.find(r=>r.path===path);const view=document.getElementById('view');if(!view)return;if(!route){view.innerHTML=UI.page('SYSTEM / 404','页面不存在','该页面没有注册在当前版本的导航中。','',`<div class="card">${UI.empty('找不到此页面','检查路由地址或返回工作总览',UI.btn('返回总览','go:overview/home','btn-primary'))}</div>`);return;}if(!this.allowed(route)){view.innerHTML=UI.page('ACCESS / 403','访问范围受限','当前身份没有访问此业务域的权限。','',`<div class="card">${UI.empty('没有访问权限','请切换到有授权的身份，或联系企业管理员开通权限。',UI.btn('返回工作总览','go:overview/home','btn-primary'))}</div>`);return;}this.current=route;document.getElementById('crumb-title').textContent=route.title;document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.route===path));view.innerHTML=route.render();},
 navigate(path){location.hash='#/'+path;},
 toast(message,type='success'){const root=document.getElementById('toast-root');root.innerHTML=`<div class="toast ${type}">${message}</div>`;setTimeout(()=>{root.innerHTML='';},2600);},
 modal(title,body,submitLabel='确认',action='modal:close'){document.getElementById('overlay-root').innerHTML=`<div class="modal-backdrop" data-action="modal:backdrop"><section class="modal"><header class="modal-head"><div class="modal-title">${title}</div><button class="icon-btn" data-action="modal:close">×</button></header><form id="modal-form"><div class="modal-body">${body}</div><footer class="modal-foot"><button type="button" class="btn" data-action="modal:close">取消</button><button type="submit" class="btn btn-primary" data-submit-action="${action}">${submitLabel}</button></footer></form></section></div>`;},
 closeModal(){document.getElementById('overlay-root').innerHTML='';},
 handleChange(e){if(e.target.id==='tenant-select'){DB.state.tenant=e.target.value;document.getElementById('side-tenant').textContent=this.tenantName();this.toast('已切换工作空间，当前列表按租户范围更新');this.renderRoute();}if(e.target.id==='project-status'){const v=e.target.value;document.querySelectorAll('.table tbody tr').forEach(r=>{r.hidden=v!=='all'&&!r.textContent.includes(v);});}if(e.target.id==='identity-select'){DB.state.identity=e.target.value;const allowed=this.availableTenants();if(allowed.length&&!allowed.some(t=>t.id===DB.state.tenant))DB.state.tenant=allowed[0].id;this.renderShell();this.renderRoute();this.toast('演示身份已切换：'+DB.roleNames[DB.state.identity]);}},
 handleClick(e){const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a.startsWith('go:'))this.navigate(a.slice(3));else if(a==='modal:close')this.closeModal();else if(a==='modal:backdrop'&&e.target===el)this.closeModal();else if(a==='project:new')this.newProject();else if(a==='script:generate')this.generateScript();else if(a==='script:approve')this.approveScript();else if(a==='script:return'){this.toast('剧本已退回修改，当前版本未锁定','error');}else if(a==='production:start')this.startProduction();else if(a==='exception:resolve')this.resolveException();else if(a==='final:approve')this.approveFinal();else if(a==='delivery:publish')this.publishDelivery();else if(a==='tenant:new')this.newTenant();else if(a==='member:invite')this.inviteMember();else if(a==='project:open'){DB.state.projectId=el.dataset.id;this.navigate('workspace/detail');}else if(a==='cross:revoke'){const item=DB.crossAuthorizations.find(x=>x.id===el.dataset.id);if(item){item.status='已撤销';this.toast('跨租户授权已撤销');this.renderRoute();}}else if(a==='asset:open')this.toast('资产详情已打开：版本、来源项目和租户归属可追溯');else if(a==='tab'){document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===el));const target=el.dataset.target;document.querySelectorAll('[data-tab-panel]').forEach(p=>p.hidden=p.dataset.tabPanel!==target);}else if(a==='filter:clear'){const input=document.querySelector('[data-filter]');if(input){input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));}}else if(a==='audit:export')this.toast('审计清单已生成演示导出任务');},
 handleSubmit(e){if(e.target.id!=='modal-form')return;e.preventDefault();const form=new FormData(e.target);const action=e.submitter?.dataset.submitAction;if(action==='project:create'){const title=form.get('title')?.trim();if(!title){this.toast('请填写项目名称','error');return;}const p={id:'SP-260'+String(50+DB.projects.length),title,genre:form.get('genre'),owner:DB.identities.find(i=>i.role===DB.state.identity)?.user||'当前员工',tenant:DB.state.tenant,episodes:Number(form.get('episodes')||12),done:0,status:'创意待启动',updated:'刚刚',stage:'创意策划',cost:0,quality:0};DB.projects.unshift(p);DB.state.scriptApproved=false;DB.state.productionStarted=false;DB.state.finalApproved=false;DB.state.delivered=false;this.closeModal();this.toast('项目已创建，进入 AI 创作流程');DB.state.projectId=p.id;this.navigate('studio/brief');}else if(action==='tenant:create'){const name=form.get('name')?.trim();if(!name)return;DB.tenants.unshift({id:'tn-'+Date.now(),name,code:'NEW-'+String(DB.tenants.length+1).padStart(2,'0'),owner:form.get('owner')||'待指定',members:0,projects:0,budget:Number(form.get('budget')||0),used:0,status:'运行中'});this.closeModal();this.toast('租户空间已创建');this.renderRoute();}else if(action==='member:invite'){DB.users.unshift({id:'u'+Date.now(),name:form.get('name'),email:form.get('email'),role:form.get('role'),tenant:DB.state.tenant,status:'待邀请',projects:0,delivered:0,cost:0});this.closeModal();this.toast('邀请已加入待发送队列');this.renderRoute();}},
 newProject(){this.modal('创建短剧项目',`<div class="form-grid">${UI.field('项目名称','title','','text','填写暂定片名，后续可修改')}${UI.select('题材方向','genre',[{value:'都市 / 情感',label:'都市 / 情感'},{value:'悬疑 / 反转',label:'悬疑 / 反转'},{value:'古装 / 爱情',label:'古装 / 爱情'},{value:'现实 / 成长',label:'现实 / 成长'}])}${UI.field('计划集数','episodes','12','number')}${UI.select('项目归属','tenant',[{value:DB.state.tenant,label:this.tenantName()}],DB.state.tenant)}<label class="field-wrap full"><span class="field-label">创作目标（可稍后补充）</span><textarea class="field" name="brief" placeholder="题材、核心冲突、受众、风格等"></textarea></label></div>`,'创建项目','project:create');},
 newTenant(){this.modal('新建内部租户空间',`<div class="notice">租户是企业内部组织与数据隔离单元，不是独立企业或 SaaS 客户。</div><div class="form-grid section-gap">${UI.field('租户名称','name')}${UI.field('负责人','owner')}${UI.field('预算上限（元）','budget','30000','number')}</div>`,'创建租户','tenant:create');},
 inviteMember(){this.modal('邀请员工加入当前租户',`<div class="form-grid">${UI.field('员工姓名','name')}${UI.field('企业邮箱','email','', 'email')}${UI.select('租户内角色','role',[{value:'employee',label:'普通员工'},{value:'tenant',label:'租户管理员'},{value:'auditor',label:'审计查看'}])}</div>`,'加入邀请队列','member:invite');},
 generateScript(){this.toast('演示流程：AI 剧本生成任务已进入队列；本原型不调用真实模型');const p=DB.projects.find(x=>x.id===DB.state.projectId);if(p){p.status='剧本待审核';p.stage='剧本审核';}this.renderRoute();},
 approveScript(){DB.state.scriptApproved=true;const p=DB.projects.find(x=>x.id===DB.state.projectId);if(p){p.status='制作准备中';p.stage='导演分镜';}this.toast('剧本 V3 已确认；演示流程进入视觉规划');this.renderRoute();},
 startProduction(){if(!DB.state.scriptApproved){this.toast('请先完成剧本审核','error');return;}DB.state.productionStarted=true;const p=DB.projects.find(x=>x.id===DB.state.projectId);if(p){p.status='制作中';p.stage='视频生产';}this.toast('生产计划已启动（演示状态），任务依赖已展开');this.renderRoute();},
 resolveException(){DB.state.exceptionResolved=true;const p=DB.projects.find(x=>x.id==='SP-26031');if(p){p.status='制作中';p.stage='音频合成';}this.toast('已选择备用音频模型并恢复受影响任务');this.renderRoute();},
 approveFinal(){DB.state.finalApproved=true;const p=DB.projects.find(x=>x.id==='SP-26038');if(p)p.status='待交付';this.toast('最终成片审核通过，允许创建交付包');this.renderRoute();},
 publishDelivery(){if(!DB.state.finalApproved){this.toast('请先完成最终成片审核','error');return;}DB.state.delivered=true;const p=DB.projects.find(x=>x.id==='SP-26038');if(p)p.status='已交付';this.toast('交付包已生成并归档（演示状态）');this.renderRoute();}
};
